CREATE OR REPLACE FUNCTION public.guard_pending_portal_ledger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN bid:=CASE WHEN TG_OP='DELETE' THEN OLD.booking_id ELSE NEW.booking_id END; IF bid IS NULL THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF; PERFORM 1 FROM public.bookings WHERE id=bid FOR UPDATE; IF EXISTS(SELECT 1 FROM public.portal_charge_requests WHERE booking_id=bid AND status NOT IN ('succeeded','canceled')) AND coalesce(current_setting('app.portal_settlement',true),'')<>'on' THEN RAISE EXCEPTION 'Resolve reserved card charge before editing payment credits'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER pending_portal_payment_guard BEFORE INSERT OR UPDATE OR DELETE ON public.payment_records FOR EACH ROW EXECUTE FUNCTION public.guard_pending_portal_ledger();
CREATE TRIGGER pending_portal_deposit_guard BEFORE INSERT OR UPDATE OR DELETE ON public.quotes FOR EACH ROW EXECUTE FUNCTION public.guard_pending_portal_ledger();
CREATE OR REPLACE FUNCTION public.settle_portal_charge(_request_id uuid,_intent_id text,_status text,_customer_id text,_amount integer,_currency text,_receipt text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.portal_charge_requests; bid uuid; BEGIN SELECT booking_id INTO bid FROM public.portal_charge_requests WHERE id=_request_id; IF bid IS NULL THEN RAISE EXCEPTION 'Unknown charge'; END IF; PERFORM 1 FROM public.bookings WHERE id=bid FOR UPDATE; SELECT * INTO r FROM public.portal_charge_requests WHERE id=_request_id FOR UPDATE; IF r.amount_cents<>_amount OR _currency<>'usd' OR (r.stripe_payment_intent_id IS NOT NULL AND r.stripe_payment_intent_id<>_intent_id) OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=r.user_id AND stripe_customer_id=_customer_id) THEN RAISE EXCEPTION 'Charge identity mismatch'; END IF; IF r.status='succeeded' AND _status<>'succeeded' THEN RETURN; END IF; PERFORM set_config('app.portal_settlement','on',true); IF _status='succeeded' THEN INSERT INTO public.payment_records(id,user_id,booking_id,stripe_payment_intent_id,stripe_customer_id,amount_cents,currency,status,payment_type,receipt_url,metadata) VALUES(r.id,r.user_id,r.booking_id,_intent_id,_customer_id,_amount,_currency,'succeeded','balance',_receipt,jsonb_build_object('portal_charge_id',r.id,'service_amount_cents',r.service_amount_cents)) ON CONFLICT(id) DO UPDATE SET status='succeeded',receipt_url=coalesce(EXCLUDED.receipt_url,payment_records.receipt_url); UPDATE public.bookings SET payment_status='paid',payment_method='online',stripe_payment_intent_id=_intent_id WHERE id=r.booking_id AND user_id=r.user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Appointment owner changed'; END IF; END IF; UPDATE public.portal_charge_requests SET status=_status,stripe_payment_intent_id=_intent_id,receipt_url=coalesce(_receipt,receipt_url),updated_at=now() WHERE id=r.id; END $$;
REVOKE ALL ON FUNCTION public.settle_portal_charge(uuid,text,text,text,integer,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.settle_portal_charge(uuid,text,text,text,integer,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.guard_reserved_booking_price() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.total_price IS DISTINCT FROM OLD.total_price OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.deposit_amount IS DISTINCT FROM OLD.deposit_amount OR NEW.guest_email IS DISTINCT FROM OLD.guest_email OR NEW.payment_status IS DISTINCT FROM OLD.payment_status OR NEW.status IN ('canceled','cancelled','no_show')) AND EXISTS(SELECT 1 FROM public.portal_charge_requests WHERE booking_id=OLD.id AND status NOT IN ('succeeded','canceled')) AND coalesce(current_setting('app.portal_settlement',true),'')<>'on' THEN RAISE EXCEPTION 'Resolve the pending card charge before changing this appointment'; END IF; RETURN NEW; END $$;